1	#!/usr/bin/env node
2	/**
3	 * FINALE-WINDOW RUNTIME WRAPPER — run-local, owned by the finale-window lane of
4	 * 2026-09-05-after-the-hearth. PREPARED HERE, NOT RUN HERE (no sink, no browser
5	 * and no recorder is created during preparation; --selftest exercises only the
6	 * stubbed error branches).
7	 *
8	 * IT IS THE CONTROL ROLE for ONE combined unmuted capture: it owns the audio
9	 * sink and the recorder; the probe (finale-window-probe.mjs) owns the browser
10	 * and the atomic state window. One run produces BOTH the atomic-state evidence
11	 * and the actual output recording; there is no second state-only capture.
12	 *
13	 * ISOLATION (audio-isolation-plan.json, unchanged in principle)
14	 *   1. Create ONE probe-owned null sink (module id remembered exactly).
15	 *   2. Launch the probe's Chromium with PULSE_SINK=<owned sink> in THAT CHILD's
16	 *      environment only. The server default sink is never set, never moved and
17	 *      is re-read afterwards to prove it is unchanged.
18	 *   3. Before recording, verify every sink-input on the owned sink belongs to
19	 *      the probe's OWN browser process tree (application.process.id must be the
20	 *      browser pid or a descendant of it). Any foreign stream => ABORT.
21	 *   4. Record ONLY <sink>.monitor. Never the default monitor, never a
22	 *      microphone, never another application's stream.
23	 *   5. Unload the module by its EXACT id in a finally and verify it is gone.
24	 *
25	 * BOUNDS
26	 *   - whole session <= --max-session-s (default 360, hard cap 360)
27	 *   - the recorder is stopped in a finally on every path, including throws,
28	 *     and the partial recording is KEPT: a failed game criterion must not
29	 *     destroy the audio evidence.
30	 *   - the recorder starts BEFORE the browser child and stops only after the
31	 *     probe's window (observed ~62 s to completion + 11.5 s hold) is sealed,
32	 *     so a 60 s whole-run recording can no longer end before completion.
33	 *
34	 * IT MAKES NO AUDIBLE OR CAUSAL CLAIM. A recording is a recording.
35	 */
36	import { mkdirSync, writeFileSync, readFileSync, existsSync, statSync } from 'node:fs';
37	import { resolve, dirname } from 'node:path';
38	import { fileURLToPath } from 'node:url';
39	import { spawn, execFileSync } from 'node:child_process';
40	import process from 'node:process';
41	
42	const HERE = dirname(fileURLToPath(import.meta.url));
43	const RUN_DIR = resolve(HERE, '..', '..', '..');
44	const REPO_ROOT = resolve(HERE, '..', '..', '..', '..', '..', '..');   // six parents: probes/verifier/run/production-runs/.codex/vox
45	
46	export const RUNTIME_SCHEMA = 'paravoxia.verifier.finaleWindowRuntime.v1';
47	export const HARD_MAX_SESSION_S = 360;
48	/** observed completion (~62 s) + the 11.5 s post-edge hold + bring-up slack. */
49	export const MIN_RECORDER_S = 62 + 11.5;
50	
51	const arg = (n, d = null) => {
52	  const i = process.argv.indexOf(`--${n}`);
53	  return i >= 0 && process.argv[i + 1] !== undefined && !process.argv[i + 1].startsWith('--') ? process.argv[i + 1] : d;
54	};
55	const tag = (m) => console.log(`[finale-window-runtime] ${m}`);
56	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
57	
58	/* ------------------------------------------------------------------ pactl -- */
59	/** Injectable so every branch below is testable with stubs and no audio server. */
60	export const realPactl = (args) =>
61	  execFileSync('pactl', args, { encoding: 'utf8', timeout: 15_000 });
62	
63	/** Parse `pactl list sink-inputs` into [{id, sink, pid, binary, appName}]. */
64	export function parseSinkInputs(text) {
65	  const out = [];
66	  for (const block of String(text).split(/\n(?=Sink Input #)/)) {
67	    const id = /Sink Input #(\d+)/.exec(block);
68	    if (!id) continue;
69	    const pid = /application\.process\.id = "(\d+)"/.exec(block);
70	    out.push({
71	      id: Number(id[1]),
72	      sink: (/\n\s*Sink: (\S+)/.exec(block) || [, null])[1],
73	      pid: pid ? Number(pid[1]) : null,
74	      binary: (/application\.process\.binary = "([^"]*)"/.exec(block) || [, null])[1],
75	      appName: (/application\.name = "([^"]*)"/.exec(block) || [, null])[1]
76	    });
77	  }
78	  return out;
79	}
80	
81	/** Parse `pactl list short modules` for our exact module id. */
82	export function moduleIdPresent(text, moduleId) {
83	  return String(text).split('\n').some((l) => l.trim().split(/\s+/)[0] === String(moduleId));
84	}
85	
86	/** Real process tree: is `pid` the browser pid or a descendant of it? */
87	export function isInProcessTree(pid, rootPid, parentOf) {
88	  if (pid == null || rootPid == null) return false;
89	  let cur = Number(pid);
90	  for (let hops = 0; hops < 24 && cur > 1; hops += 1) {
91	    if (cur === Number(rootPid)) return true;
92	    const next = parentOf(cur);
93	    if (next == null || next === cur) return false;
94	    cur = next;
95	  }
96	  return false;
97	}
98	
99	export const realParentOf = (pid) => {
100	  try {
101	    const stat = readFileSync(`/proc/${pid}/stat`, 'utf8');
102	    const after = stat.slice(stat.lastIndexOf(')') + 2).split(' ');
103	    return Number(after[1]);
104	  } catch { return null; }
105	};
106	
107	/**
108	 * OWNERSHIP GATE. Returns {ok, reason, streams}. It is a REFUSAL, not a
109	 * warning: a foreign stream on the owned sink means the recording would be a
110	 * mixed capture and must not be taken.
111	 */
112	export function verifySinkOwnership({ sinkName, sinkIndex, browserPid, sinkInputs, parentOf = realParentOf }) {
113	  const mine = sinkInputs.filter((s) => s.sink === sinkName || String(s.sink) === String(sinkIndex));
114	  if (mine.length === 0) {
115	    return { ok: false, reason: 'no-stream-on-owned-sink', streams: mine };
116	  }
117	  const foreign = mine.filter((s) => !isInProcessTree(s.pid, browserPid, parentOf));
118	  if (foreign.length > 0) {
119	    return { ok: false, reason: 'foreign-stream-on-owned-sink', streams: mine, foreign };
120	  }
121	  return { ok: true, reason: 'all-streams-in-probe-browser-process-tree', streams: mine };
122	}
123	
124	/* ------------------------------------------------------------- the session -- */
125	export async function runCombinedCapture(opts) {
126	  const {
127	    outDir, sinkName = 'paravoxia_finale_window',
128	    maxSessionS = HARD_MAX_SESSION_S, recorderMinS = MIN_RECORDER_S,
129	    pactl = realPactl, spawnFn = spawn, parentOf = realParentOf,
130	    probeArgs = [], log = tag, now = () => Date.now()
131	  } = opts;
132	
133	  if (maxSessionS > HARD_MAX_SESSION_S) throw new Error(`session bound ${maxSessionS}s exceeds hard cap ${HARD_MAX_SESSION_S}s`);
134	  if (recorderMinS < MIN_RECORDER_S) throw new Error(`recorder lifetime ${recorderMinS}s is shorter than the observed completion+hold (${MIN_RECORDER_S}s)`);
135	  mkdirSync(outDir, { recursive: true });
136	
137	  const record = {
138	    schema: RUNTIME_SCHEMA, startedAt: new Date().toISOString(),
139	    outcome: 'NOT-COMPLETED', outcomeIsAcceptance: false,
140	    audibleClaim: 'none — this wrapper records bytes; it makes no audible, causal or acceptance claim',
141	    sinkName, moduleId: null, browserPid: null, defaultSinkBefore: null, defaultSinkAfter: null,
142	    ownership: null, recorder: null, probe: null, phases: [], errors: []
143	  };
144	  const phase = (name, extra = {}) => { record.phases.push({ name, atMs: now(), ...extra }); log(name); };
145	
146	  let moduleId = null;
147	  let recorder = null;
148	  let recorderStopped = false;
149	  const audioPath = resolve(outDir, 'owned-sink.wav');
150	
151	  const stopRecorder = async (reason) => {
152	    if (!recorder || recorderStopped) return;
153	    recorderStopped = true;
154	    try { recorder.kill('SIGINT'); } catch { /* already gone */ }
155	    const deadline = now() + 5000;
156	    while (recorder.exitCode === null && now() < deadline) await sleep(100);
157	    if (recorder.exitCode === null) { try { recorder.kill('SIGKILL'); } catch { /* gone */ } }
158	    record.recorder = {
159	      ...(record.recorder || {}), stopReason: reason, stoppedAtMs: now(),
160	      exitCode: recorder.exitCode,
161	      bytes: existsSync(audioPath) ? statSync(audioPath).size : 0,
162	      file: audioPath,
163	      preserved: true,
164	      note: 'The recording is kept on EVERY path, including a failed game criterion, so failure audio is never destroyed.'
165	    };
166	    phase('recorder-stopped', { reason, bytes: record.recorder.bytes });
167	  };
168	
169	  try {
170	    record.defaultSinkBefore = String(pactl(['get-default-sink'])).trim();
171	    phase('default-sink-read', { defaultSink: record.defaultSinkBefore });
172	
173	    // 1. own sink
174	    moduleId = String(pactl(['load-module', 'module-null-sink', `sink_name=${sinkName}`,
175	      `sink_properties=device.description=${sinkName}`])).trim();
176	    record.moduleId = moduleId;
177	    phase('owned-sink-created', { moduleId });
178	
179	    // 2. the probe's own browser, pointed at the owned sink through ITS env only
180	    const probe = spawnFn(process.execPath,
181	      [resolve(HERE, 'finale-window-probe.mjs'), '--pulse-sink', sinkName, ...probeArgs],
182	      { stdio: ['ignore', 'pipe', 'pipe'], env: process.env });
183	    const probeLog = [];
184	    probe.stdout?.on('data', (d) => probeLog.push(String(d)));
185	    probe.stderr?.on('data', (d) => probeLog.push(String(d)));
186	    phase('probe-launched', { probePid: probe.pid });
187	
188	    // 3. the REAL browser pid, published by the probe. Never mocked.
189	    const pidFile = resolve(outDir, 'browser-pid.json');
190	    const pidDeadline = now() + 120_000;
191	    while (!existsSync(pidFile) && now() < pidDeadline && probe.exitCode === null) await sleep(250);
192	    if (!existsSync(pidFile)) throw new Error('probe never published browser-pid.json; refusing to record without a verified owner');
193	    record.browserPid = JSON.parse(readFileSync(pidFile, 'utf8')).browserPid;
194	    if (!record.browserPid) throw new Error('probe published a null browser pid; refusing to record without a verified owner');
195	    phase('browser-pid-observed', { browserPid: record.browserPid });
196	
197	    // 4. ownership gate BEFORE any recording
198	    let ownership = { ok: false, reason: 'not-checked' };
199	    const ownDeadline = now() + 90_000;
200	    while (now() < ownDeadline) {
201	      ownership = verifySinkOwnership({
202	        sinkName, sinkIndex: null, browserPid: record.browserPid,
203	        sinkInputs: parseSinkInputs(pactl(['list', 'sink-inputs'])), parentOf
204	      });
205	      if (ownership.ok) break;
206	      if (ownership.reason === 'foreign-stream-on-owned-sink') break;   // never wait out a foreign stream
207	      await sleep(1000);
208	    }
209	    record.ownership = ownership;
210	    if (!ownership.ok) throw new Error(`sink ownership refused: ${ownership.reason}`);
211	    phase('ownership-verified', { streams: ownership.streams.length });
212	
213	    // 5. record ONLY the owned sink's own monitor
214	    recorder = spawnFn('parec', ['-d', `${sinkName}.monitor`, '--file-format=wav', audioPath],
215	      { stdio: ['ignore', 'ignore', 'pipe'] });
216	    record.recorder = { pid: recorder.pid, device: `${sinkName}.monitor`, startedAtMs: now(),
217	      plannedMinSeconds: recorderMinS, isMicrophone: false, isDefaultMonitor: false };
218	    phase('recorder-started', { device: `${sinkName}.monitor`, pid: recorder.pid });
219	
220	    // 6. wait for the probe, bounded by the whole-session cap AND never shorter
221	    //    than the completion+hold the recorder must cover.
222	    const sessionDeadline = now() + maxSessionS * 1000;
223	    while (probe.exitCode === null && now() < sessionDeadline) await sleep(500);
224	    const elapsedS = (now() - record.recorder.startedAtMs) / 1000;
225	    if (probe.exitCode === null) {
226	      record.probe = { exitCode: null, timedOut: true, elapsedS };
227	      throw new Error(`probe did not finish within the ${maxSessionS}s session bound`);
228	    }
229	    record.probe = { exitCode: probe.exitCode, timedOut: false, elapsedS,
230	      coveredCompletionPlusHold: elapsedS >= recorderMinS, log: probeLog.join('').slice(-4000) };
231	    writeFileSync(resolve(outDir, 'probe-console.log'), probeLog.join(''));
232	    record.outcome = probe.exitCode === 0 ? 'CAPTURED-NO-VERDICT' : 'PROBE-FAILED-AUDIO-PRESERVED';
233	    return record;
234	  } catch (error) {
235	    record.errors.push(String(error && error.stack ? error.stack : error).slice(0, 800));
236	    record.outcome = record.outcome === 'NOT-COMPLETED' ? 'FAILED-AUDIO-PRESERVED' : record.outcome;
237	    throw Object.assign(error, { runtimeRecord: record });
238	  } finally {
239	    // Recorder first, then the sink: stopping the reader before removing what
240	    // it reads keeps the wav finalized.
241	    await stopRecorder('finally');
242	    if (moduleId) {
243	      try {
244	        pactl(['unload-module', moduleId]);
245	        const gone = !moduleIdPresent(pactl(['list', 'short', 'modules']), moduleId);
246	        record.sinkTeardown = { moduleId, unloaded: true, verifiedGone: gone };
247	        if (!gone) record.errors.push(`owned sink module ${moduleId} still present after unload`);
248	      } catch (e) {
249	        record.sinkTeardown = { moduleId, unloaded: false, verifiedGone: false, error: String(e).slice(0, 300) };
250	        record.errors.push(`unload-module ${moduleId} failed: ${String(e).slice(0, 200)}`);
251	      }
252	    }
253	    try {
254	      record.defaultSinkAfter = String(pactl(['get-default-sink'])).trim();
255	      record.defaultSinkUnchanged = record.defaultSinkAfter === record.defaultSinkBefore;
256	      if (!record.defaultSinkUnchanged) record.errors.push('server default sink CHANGED across the session');
257	    } catch (e) { record.errors.push(`default-sink re-read failed: ${String(e).slice(0, 200)}`); }
258	    record.endedAt = new Date().toISOString();
259	    try { writeFileSync(resolve(outDir, 'runtime-record.json'), JSON.stringify(record, null, 1)); } catch { /* reported below */ }
260	  }
261	}
262	
263	/* ------------------------------------------------------------------- main -- */
264	if (import.meta.url === `file://${process.argv[1]}`) {
265	  const outDir = arg('out', null);
266	  if (!outDir) { console.error('--out <abs dir> is required'); process.exit(2); }
267	  runCombinedCapture({
268	    outDir: resolve(outDir),
269	    sinkName: arg('sink', 'paravoxia_finale_window'),
270	    maxSessionS: Number(arg('max-session-s', String(HARD_MAX_SESSION_S))),
271	    probeArgs: process.argv.slice(process.argv.indexOf('--probe-args') + 1)
272	      .filter(() => process.argv.includes('--probe-args'))
273	  }).then((r) => { tag(`${r.outcome}; record -> ${resolve(outDir, 'runtime-record.json')}`); })
274	    .catch((e) => { console.error(`[finale-window-runtime] FAILED: ${e.stack ?? e}`); process.exit(1); });
275	}
276

